import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const dir = join(root, "node_modules/@material-symbols/svg-400/outlined");

const names = `
menu search tune close help settings apps edit inbox star schedule label_important send schedule_send draft mail report
delete expand_more expand_less label add more_vert more_horiz refresh chevron_left chevron_right arrow_back arrow_forward archive unarchive
mark_email_unread mark_email_read drafts drive_file_move new_label label_off reply reply_all forward print open_in_new attach_file
image link mood text_format format_bold format_italic format_underlined format_list_bulleted format_list_numbered format_quote
format_strikethrough format_clear format_align_left format_align_center format_align_right format_indent_increase format_indent_decrease
undo redo remove open_in_full close_fullscreen arrow_drop_down check_box_outline_blank check_box indeterminate_check_box download visibility
picture_as_pdf description table_chart slideshow folder_zip sell group info forum dark_mode light_mode contrast logout person_add
manage_accounts account_circle lock keyboard block unsubscribe event calendar_today check done location_on videocam today weekend
date_range notifications signature vertical_split horizontal_split view_agenda content_copy error warning restart_alt mail_lock
contacts filter_list attachment photo_library cloud_done person keyboard_arrow_down keyboard_arrow_up flight receipt_long credit_card
shopping_bag local_shipping code movie audio_file split_scene view_headline density_small density_medium density_large report_off
move_to_inbox outbox all_inbox stars delete_forever keep add_task task_alt lightbulb bolt palette font_download format_color_text
text_fields emoji_emotions send_and_archive history cancel check_circle help_center feedback desktop_windows smartphone wifi_off
cloud_off sync arrow_upward arrow_downward drag_indicator thumb_up favorite celebration visibility_off workspace_premium
filter_alt keyboard_command_key person_search mark_chat_unread swap_vert sort format_size translate public tag notifications_off
markunread_mailbox inventory_2 pending event_available event_busy help_outline question_mark
`.trim().split(/\s+/);

const out = {};
const missing = [];
for (const name of names) {
  for (const [key, file] of [
    [name, `${name}.svg`],
    [`${name}_fill`, `${name}-fill.svg`],
  ]) {
    const p = join(dir, file);
    if (!existsSync(p)) {
      if (key === name) missing.push(name);
      continue;
    }
    const svg = readFileSync(p, "utf8");
    const paths = [...svg.matchAll(/<path d="([^"]+)"/g)].map((m) => m[1]);
    out[key] = paths.join(" ");
  }
}

const body = `// Generated by scripts/gen-icons.mjs from @material-symbols/svg-400 (Apache-2.0). Do not edit.\nexport const ICONS = ${JSON.stringify(out, null, 0).replace(/","/g, '",\n"')} as const;\nexport type IconName = keyof typeof ICONS;\n`;
writeFileSync(join(root, "src/components/icons-data.ts"), body);
console.log(`wrote ${Object.keys(out).length} icons`);
if (missing.length) console.log("missing:", missing.join(", "));

