  for (const line of lines.flatMap((l) => (l === "" ? [""] : wrap(l, 92)))) {
    if (y < 56) break;
    const heading = line.startsWith("## ");
    const txt = heading ? line.slice(3) : line;
    stream += `BT /${heading ? "F2" : "F1"} ${heading ? 13 : 11} Tf 0.2 0.2 0.2 rg 56 ${y} Td (${pdfEscape(txt)}) Tj ET\n`;
    y -= heading ? 22 : 16;
