    case "pdf":
    case "doc":
      return makePdf(seed?.title || att.name.replace(/\.[^.]+$/, ""), seed?.lines || []);
    case "sheet": {
      const csv = (seed?.rows || []).map((r) => r.map((c) => (/[",\n]/.test(c) ? `"${c.replace(/"/g, '""')}"` : c)).join(",")).join("\n");
