+            html: init.html ?? (init.kind === "forward" ? fwd : `<p></p>${sig}`),
+            text: "",
+            attachments: init.kind === "forward" ? orig.attachments.map((a) => ({ ...a, id: uid("att") })) : [],
+            status: "draft",
+            quoted,
+            replyKind: init.kind,
