@import "tailwindcss";

@custom-variant dark (&:where(.dark, .dark *));

@theme inline {
  --font-sans: "Google Sans", Roboto, "Helvetica Neue", Arial, sans-serif;
  --font-body: Roboto, "Helvetica Neue", Arial, sans-serif;
  --color-bg: var(--bg);
  --color-surface: var(--surface);
  --color-surface-2: var(--surface-2);
  --color-surface-3: var(--surface-3);
  --color-menu: var(--menu-bg);
  --color-fg: var(--text);
  --color-fg-2: var(--text-2);
  --color-fg-3: var(--text-3);
  --color-icon: var(--icon);
  --color-line: var(--divider);
  --color-outline: var(--border);
  --color-outline-soft: var(--border-soft);
  --color-primary: var(--primary);
  --color-on-primary: var(--on-primary);
  --color-primary-soft: var(--primary-soft);
  --color-on-primary-soft: var(--on-primary-soft);
  --color-compose: var(--compose);
  --color-on-compose: var(--on-compose);
  --color-hover: var(--hover);
  --color-hover-strong: var(--hover-strong);
  --color-search: var(--search-bg);
  --color-star: var(--star);
  --color-danger: var(--danger);
  --color-snackbar: var(--snackbar);
  --color-on-snackbar: var(--on-snackbar);
  --color-snackbar-action: var(--snackbar-action);
  --color-row-read: var(--row-read);
  --color-row-unread: var(--row-unread);
  --color-row-selected: var(--row-selected);
  --shadow-e1: var(--shadow-1);
  --shadow-e2: var(--shadow-2);
  --shadow-e3: var(--shadow-3);
  --animate-pop: pop 0.16s cubic-bezier(0.2, 0, 0, 1);
  --animate-fade: fade 0.15s ease-out;
  --animate-rise: rise 0.22s cubic-bezier(0.2, 0, 0, 1);
