export function useStorage() {
  const messages = useMail((s) => s.messages);
  return useMemo(() => {
    let bytes = 1_180_000_000;
    for (const m of Object.values(messages)) bytes += m.html.length + m.attachments.reduce((n, a) => n + a.size, 0);
    return { used: bytes, total: 15 * 1024 ** 3 };
  }, [messages]);
}

