              className={cn("-mr-2 -mt-1 inline-flex size-10 shrink-0 items-center justify-center rounded-full", t.starred ? "text-star" : "text-fg-3")}
            >
              <Icon name="star" fill={t.starred} size={22} />
            </button>
          </div>
        </div>
      </div>
    </div>
