function rng(seed: number) {
  let s = seed % 2147483647 || 1;
  return () => (s = (s * 16807) % 2147483647) / 2147483647;
}

export type ArtVariant = "landscape" | "ocean" | "ui" | "chart" | "banner" | "portrait";

