export function imageVariantFor(att: Attachment): ArtVariant {
  const n = att.name.toLowerCase();
  if (/(screen|mock|nav|ui|explor|design|wireframe)/.test(n)) return "ui";
  if (/(chart|timeline|graph|metrics)/.test(n)) return "chart";
