        <span className="text-fg-3">· Scanned for viruses</span>
        {shown.length > 1 && <IconButton icon="download" label="Download all" size="sm" className="ml-auto" onClick={downloadAll} />}
      </div>
      <div className="flex flex-wrap gap-3">
        {shown.map((a) => (
          <div
            key={a.id}
