            <button type="button" onClick={() => ui().set({ sidePanel: "contacts" })} className="ml-auto rounded-full px-3 py-2 text-sm font-medium text-primary hover:bg-hover">
              Open contact
            </button>
          </div>
        </HoverCard.Content>
      </HoverCard.Portal>
