  );

  if (maximized) {
    return (
      <div className="pointer-events-auto fixed inset-0 z-[72] flex items-center justify-center bg-[var(--scrim)] animate-fade" onMouseDown={(e) => e.target === e.currentTarget && ui().updateComposer(id, { maximized: false })}>
