+    const m = getMail().messages[id];
+    if (!m) return;
+    getMail().updateDraft(id, { attachments: [...m.attachments, ...atts] });
+    setStatus("saved");
+  };
+
+  const removeAttachment = (a: Attachment) => {
+    const m = getMail().messages[id];
