/** Tokenizes Gmail-style queries: from:x "exact phrase" -term subject:(a b) OR. */
export function parseQuery(raw: string): ParsedQuery {
  const terms: Term[] = [];
  const re = /(-)?(?:([a-z_]+):)?(?:"([^"]*)"|\(([^)]*)\)|(\S+))/gi;
  let m: RegExpExecArray | null;
  while ((m = re.exec(raw))) {
