}

/* ---------- Message body ---------- */
.mail-body {
  font-family: var(--font-body);
  font-size: 14px;
  line-height: 1.55;
  color: var(--text);
  overflow-wrap: anywhere;
}
.mail-body p { margin: 0 0 0.85em; }
.mail-body p:last-child { margin-bottom: 0; }
.mail-body ul, .mail-body ol { margin: 0 0 0.85em; padding-left: 1.6em; }
.mail-body ul { list-style: disc; }
.mail-body ol { list-style: decimal; }
.mail-body li { margin: 0.2em 0; }
.mail-body a { color: var(--mail-link); text-decoration: underline; }
.mail-body img { max-width: 100%; height: auto; }
.mail-body h1, .mail-body h2, .mail-body h3 { font-weight: 600; }
.mail-body code { font-family: ui-monospace, Menlo, monospace; font-size: 12.5px; background: var(--surface-3); padding: 1px 5px; border-radius: 4px; }
.mail-body blockquote, .mail-quote {
  margin: 0.4em 0 0.4em 0.8ex;
  border-left: 1px solid var(--border);
  padding-left: 1ex;
  color: var(--text-2);
}
.mail-quote-attr { color: var(--text-3); margin: 0.8em 0 0.4em; }
.mail-signature { color: var(--text-3); }
.mail-forward { margin-top: 0.8em; }
.mail-body mark, .hl { background: #fde293; color: inherit; border-radius: 2px; padding: 0 1px; }
.dark .mail-body mark, .dark .hl { background: #7a5c00; }
.dark .mail-body.mail-rich > div[style*="max-width"] {
  filter: none;
}

/* ---------- Composer editor ---------- */
.compose-editor .ProseMirror {
  outline: none;
  min-height: 100%;
  font-family: var(--font-body);
  font-size: 14px;
  line-height: 1.5;
  color: var(--text);
  padding: 4px 0 8px;
}
.compose-editor .ProseMirror p { margin: 0; min-height: 1.5em; }
.compose-editor .ProseMirror ul, .compose-editor .ProseMirror ol { padding-left: 1.6em; margin: 0.3em 0; }
.compose-editor .ProseMirror ul { list-style: disc; }
.compose-editor .ProseMirror ol { list-style: decimal; }
.compose-editor .ProseMirror blockquote { border-left: 2px solid var(--border); margin: 0.4em 0; padding-left: 10px; color: var(--text-2); }
.compose-editor .ProseMirror a { color: var(--mail-link); text-decoration: underline; }
.compose-editor .ProseMirror code { font-family: ui-monospace, Menlo, monospace; background: var(--surface-3); padding: 1px 4px; border-radius: 4px; }
.compose-editor .ProseMirror .mail-signature, .compose-editor .ProseMirror div { color: inherit; }
.compose-editor .ProseMirror p.is-editor-empty:first-child::before {
  content: attr(data-placeholder);
  color: var(--text-3);
  float: left;
  height: 0;
  pointer-events: none;
}

/* ---------- Utilities ---------- */
.no-scrollbar { scrollbar-width: none; }
.no-scrollbar::-webkit-scrollbar { display: none; }
.row-hover:hover { box-shadow: var(--row-hover); z-index: 2; }
.safe-bottom { padding-bottom: env(safe-area-inset-bottom); }
.label-chip {
  background: color-mix(in srgb, var(--chip) 22%, var(--surface));
  color: color-mix(in srgb, var(--chip) 55%, var(--text));
}
.dark .label-chip {
  background: color-mix(in srgb, var(--chip) 30%, var(--surface));
  color: color-mix(in srgb, var(--chip) 40%, #fff);
}

@media print {
  body { background: #fff; overflow: visible; }
  .no-print { display: none !important; }
  .print-area { position: static !important; overflow: visible !important; height: auto !important; box-shadow: none !important; margin: 0 !important; border-radius: 0 !important; }
  #root, .app-shell { height: auto !important; overflow: visible !important; display: block !important; }
}

