            <Button variant="text" onClick={() => (ui().closeComposer(props.id), reset())}>Close</Button>
            <Button onClick={reset}>Try again</Button>
          </div>
        </div>
      )}
    >
      <Suspense fallback={null}>
        <Inner {...props} />
      </Suspense>
    </ErrorBoundary>
  );
}
